// CDL3BLACKCROWSLookback returns how many leading bars [Core.CDL3BLACKCROWS]
// consumes before its first value: called with startIdx 0, its first value is
// at that bar.
func (c *Core) CDL3BLACKCROWSLookback() (int, error) {
	lookback := c.cdl3blackcrowsLookback()
	if lookback < 0 {
		return 0, BadParam
	}
	return int(lookback), nil
}

// CDL3BLACKCROWSDisplayShift returns how many bars ahead (positive) or behind
// (negative) of the bar that computed it a chart draws output outputIdx of
// [Core.CDL3BLACKCROWS]. The values are never shifted.
//
// Every output of this function is drawn at its own bar, so the answer is 0.
//
// It takes the output's position among the outputs of [Core.CDL3BLACKCROWS],
// from 0, and returns [BadParam] for an index that names no output.
func (c *Core) CDL3BLACKCROWSDisplayShift(outputIdx int) (int, error) {
	if outputIdx < 0 || outputIdx >= 1 {
		return 0, BadParam
	}
	return 0, nil
}

// CDL3BLACKCROWS recognizes the Three Black Crows pattern over bars startIdx
// through endIdx.
//
// A four-bar pattern: a white candle followed by three consecutive black (down)
// candles with successively lower closes, each opening inside the prior black's
// real body. It is a bearish reversal signal. A hit (-100) signals a bearish
// reversal.
//
// Formula and more info at https://ta-lib.org/functions/cdl3blackcrows.
//
// Inputs, each at least endIdx+1 long:
//   - inOpen: Open price of each bar.
//   - inHigh: High price of each bar.
//   - inLow: Low price of each bar.
//   - inClose: Close price of each bar.
//
// Outputs, each at least as long as the values written (the input length always
// suffices):
//   - outInteger: -100 when the bearish pattern is detected, 0 otherwise. Never
//     emits +100.
//
// Element k of each output is the value at bar BegIdx+k of the returned
// [OutRange], and BegIdx is at least [Core.CDL3BLACKCROWSLookback]: a range
// that ends before it returns NBElement 0.
//
// The error is [OutOfRangeStartIndex] or [OutOfRangeEndIndex] for a range
// outside 0 to [IndexMax] or ending before it starts, and [BadParam] for an
// input too short or an output empty or too short.
func (c *Core) CDL3BLACKCROWS(startIdx, endIdx int, inOpen, inHigh, inLow, inClose []float64, outInteger []int32) (OutRange, error) {
	if startIdx < 0 || startIdx > IndexMax {
		return OutRange{}, OutOfRangeStartIndex
	}
	if endIdx < 0 || endIdx > IndexMax || endIdx < startIdx {
		return OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdl3blackcrowsLookback())
	if lookback < 0 {
		return OutRange{}, BadParam
	}
	if len(inOpen) < endIdx+1 {
		return OutRange{}, BadParam
	}
	if len(inHigh) < endIdx+1 {
		return OutRange{}, BadParam
	}
	if len(inLow) < endIdx+1 {
		return OutRange{}, BadParam
	}
	if len(inClose) < endIdx+1 {
		return OutRange{}, BadParam
	}
	outLen := requiredOut(startIdx, endIdx, lookback)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	if retCode := c.cdl3blackcrowsImpl(int32(startIdx), int32(endIdx), inOpen, inHigh, inLow, inClose, &outBegIdx, &outNBElement, outInteger); retCode != Success {
		return OutRange{}, retCode
	}
	return OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}

// CDL3BLACKCROWSStream is a live CDL3BLACKCROWS over a growing series:
// [CDL3BLACKCROWSStream.Update] takes each new closed bar and returns the value
// [Core.CDL3BLACKCROWS] computes at that bar over the same series. Open one
// with [Core.CDL3BLACKCROWSOpen] or [Core.CDL3BLACKCROWSOpenAndFill].
//
// A stream belongs to one goroutine; [CDL3BLACKCROWSStream.Clone] forks it.
